import React, { useState } from 'react';

// Mock data - In the future, this will come from your Django API
const initialLeaveRequests = [
  { id: 1, employeeName: 'Dr. Anjali Rao', department: 'Computer Science', startDate: '2025-11-10', endDate: '2025-11-12', leaveType: 'Casual Leave', status: 'Pending' },
  { id: 2, employeeName: 'Mr. Vikram Singh', department: 'Library', startDate: '2025-11-15', endDate: '2025-11-15', leaveType: 'Sick Leave', status: 'Approved' },
  { id: 3, employeeName: 'Sunita Sharma', department: 'Admissions Office', startDate: '2025-12-01', endDate: '2025-12-05', leaveType: 'Annual Leave', status: 'Pending' },
  { id: 4, employeeName: 'Rajesh Kumar', department: 'Physics', startDate: '2025-10-20', endDate: '2025-10-21', leaveType: 'Sick Leave', status: 'Denied' },
  { id: 5, employeeName: 'Priya Mehta', department: 'Administration', startDate: '2025-11-20', endDate: '2025-11-22', leaveType: 'Casual Leave', status: 'Approved' },
];

const LeaveTrackerPage = () => {
  // 1. Use useState to hold the list of leave requests, starting with our mock data.
  const [leaveRequests, setLeaveRequests] = useState(initialLeaveRequests);

  // 2. This function handles the "Approve" or "Deny" action.
  const handleStatusUpdate = (requestId, newStatus) => {
    console.log(`Updating request ${requestId} to ${newStatus}`);

    // Create a new array by mapping over the old one. This is the correct way to update state in React.
    const updatedRequests = leaveRequests.map(request => {
      // If this is the request we want to update...
      if (request.id === requestId) {
        // ...return a new object with the updated status.
        return { ...request, status: newStatus };
      }
      // Otherwise, return the original, unchanged request.
      return request;
    });

    // 3. Update the state with the new array, which will cause the component to re-render.
    setLeaveRequests(updatedRequests);
  };

  // Helper function to get the color class for a status badge
  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'Approved':
        return 'bg-green-100 text-green-800';
      case 'Pending':
        return 'bg-yellow-100 text-yellow-800';
      case 'Denied':
        return 'bg-red-100 text-red-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <>
      <header className="bg-card-light dark:bg-card-dark p-4 flex justify-between items-center border-b border-border-light dark:border-border-dark sticky top-0">
        <h1 className="text-2xl font-semibold text-text-light dark:text-text-dark">Leave Management</h1>
        <button className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center hover:bg-blue-600">
          <span className="material-icons mr-2 text-base">add</span> Request Leave
        </button>
      </header>

      <div className="p-8">
        <div className="bg-card-light dark:bg-card-dark p-6 rounded-lg shadow-md">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-subtext-light dark:text-subtext-dark uppercase bg-background-light dark:bg-background-dark">
              <tr>
                <th className="px-6 py-3">Employee Name</th>
                <th className="px-6 py-3">Department</th>
                <th className="px-6 py-3">Dates</th>
                <th className="px-6 py-3">Type</th>
                <th className="px-6 py-3">Status</th>
                <th className="px-6 py-3 text-center">Actions</th>
              </tr>
            </thead>
            <tbody>
              {leaveRequests.map((request) => (
                <tr key={request.id} className="border-b border-border-light dark:border-border-dark hover:bg-gray-50 dark:hover:bg-gray-800/50">
                  <td className="px-6 py-4 font-medium text-text-light dark:text-text-dark">{request.employeeName}</td>
                  <td className="px-6 py-4">{request.department}</td>
                  <td className="px-6 py-4">{request.startDate} to {request.endDate}</td>
                  <td className="px-6 py-4">{request.leaveType}</td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusBadgeClass(request.status)}`}>
                      {request.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center space-x-2">
                    {/* 4. Conditionally render buttons based on the request status */}
                    {request.status === 'Pending' ? (
                      <>
                        <button 
                          onClick={() => handleStatusUpdate(request.id, 'Approved')}
                          className="text-green-600 hover:text-green-800 font-semibold"
                        >
                          Approve
                        </button>
                        <button 
                          onClick={() => handleStatusUpdate(request.id, 'Denied')}
                          className="text-red-600 hover:text-red-800 font-semibold"
                        >
                          Deny
                        </button>
                      </>
                    ) : (
                      <span className="text-xs text-subtext-light">No actions</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
};

export default LeaveTrackerPage;
